/// The deployment manifest, for code that reads it directly rather than keeping
/// its own copy of the addresses (docs/agent-to-agent.md, 2a). Generated by
/// `scripts/build-deployments.ts` from what is deployed; new code, like the
/// event indexer, starts here. `celo-mainnet.json` beside this file is the
/// script's second copy of `deployments/celo-mainnet.json`, because a deploy
/// bundles only what is under `supabase/functions`.
import manifest from "./celo-mainnet.json" with { type: "json" };

export const DEPLOYMENT = manifest;
export const CHAIN_ID = manifest.chain.chainId;

export const V5 = {
  address: manifest.contracts.RemessoExecutorV5.address.toLowerCase() as `0x${string}`,
  deployBlock: BigInt(manifest.contracts.RemessoExecutorV5.deployBlock),
};
export const ALLOWANCE = {
  address: manifest.contracts.RemessoAgentAllowance.address.toLowerCase() as `0x${string}`,
  deployBlock: BigInt(manifest.contracts.RemessoAgentAllowance.deployBlock),
};
